create schema if not exists ouf_mcp;
create table if not exists ouf_mcp.manifest_snapshot(manifest_checksum char(64) primary key check(manifest_checksum~'^[0-9a-f]{64}$'),manifest_version text not null,schema_version text not null,payload jsonb not null,created_at timestamptz not null default transaction_timestamp());
create or replace function ouf_mcp.reject_mutation() returns trigger language plpgsql as $$ begin raise exception 'append-only relation %',tg_table_name; end $$;
create trigger manifest_snapshot_immutable before update or delete on ouf_mcp.manifest_snapshot for each row execute function ouf_mcp.reject_mutation();
create table if not exists ouf_mcp.application_session(application_session_id uuid primary key,application_conversation_ref text,service_principal_id text not null,principal_id text not null,tenant_id text not null,created_manifest_checksum char(64) not null references ouf_mcp.manifest_snapshot(manifest_checksum),created_at timestamptz not null default transaction_timestamp(),expires_at timestamptz not null,check(expires_at>created_at));
create index if not exists application_session_expiry_idx on ouf_mcp.application_session(expires_at);
create table if not exists ouf_mcp.tool_attempt(attempt_id uuid primary key,application_session_id uuid references ouf_mcp.application_session(application_session_id),service_principal_id text not null,principal_id text not null,tenant_id text not null,capability_id text not null,operation_class text not null,manifest_checksum char(64) not null references ouf_mcp.manifest_snapshot(manifest_checksum),idempotency_key text not null,request_hash char(64) not null check(request_hash~'^[0-9a-f]{64}$'),correlation_id text not null,state text not null check(state in('ADMITTED','RUNNING','SUCCEEDED','FAILED','UNKNOWN','UNRESOLVED')),dispatch_state text not null check(dispatch_state in('NOT_DISPATCHED','DISPATCHED','CONFIRMED','UNKNOWN')),backend_request_id text,admitted_at timestamptz not null default transaction_timestamp(),started_at timestamptz,completed_at timestamptz,lease_until timestamptz,lock_version bigint not null default 0,unique(service_principal_id,principal_id,tenant_id,capability_id,operation_class,idempotency_key),check((state='RUNNING')=(lease_until is not null)),check((state in('SUCCEEDED','FAILED','UNRESOLVED'))=(completed_at is not null)));
create index if not exists tool_attempt_orphan_idx on ouf_mcp.tool_attempt(lease_until) where state='RUNNING';
create table if not exists ouf_mcp.audit_event(sequence_id bigint generated always as identity primary key,audit_event_id uuid not null unique,event_type text not null,actor_type text not null,service_principal_id text,attempt_id uuid references ouf_mcp.tool_attempt(attempt_id),manifest_checksum char(64) references ouf_mcp.manifest_snapshot(manifest_checksum),safe_detail jsonb not null default '{}'::jsonb,occurred_at timestamptz not null default transaction_timestamp(),check(not(safe_detail ?| array['token','authorization','cookie','password','secret'])));
create trigger audit_event_append_only before update or delete on ouf_mcp.audit_event for each row execute function ouf_mcp.reject_mutation();
